<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['form']??'')==='ward'){$s=$pdo->prepare('INSERT INTO wards(name,type,capacity) VALUES(?,?,?)');$s->execute([trim($_POST['name']),$_POST['type'],(int)$_POST['capacity']]);flash('Ward created.');}else{$s=$pdo->prepare('INSERT INTO beds(ward_id,bed_no,gender_restriction,status) VALUES(?,?,?,"Available")');$s->execute([(int)$_POST['ward_id'],trim($_POST['bed_no']),$_POST['gender_restriction']]);flash('Bed added.');}redirect('wards.php');}$wards=$pdo->query('SELECT w.*,COUNT(b.id) bed_count,SUM(b.status="Occupied") occupied FROM wards w LEFT JOIN beds b ON b.ward_id=w.id GROUP BY w.id ORDER BY w.name')->fetchAll();admin_header('Wards & Beds','wards.php');?><div class="grid"><div class="card"><h2>Add ward</h2><form method="post"><?=csrf_field()?><input type="hidden" name="form" value="ward"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Type</label><select name="type"><option>General</option><option>Private</option><option>Maternity</option><option>Paediatrics</option><option>ICU</option><option>Other</option></select></div><div class="field"><label>Capacity</label><input type="number" name="capacity" min="0" value="1"></div><button style="margin-top:12px">Save ward</button></form></div><div class="card"><h2>Add bed</h2><form method="post"><?=csrf_field()?><input type="hidden" name="form" value="bed"><div class="field"><label>Ward</label><select name="ward_id" required><?php foreach($wards as $w):?><option value="<?=$w['id']?>"><?=e($w['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Bed number</label><input name="bed_no" required></div><div class="field"><label>Gender restriction</label><select name="gender_restriction"><option>Any</option><option>Male</option><option>Female</option></select></div><button style="margin-top:12px">Add bed</button></form></div></div><div class="card" style="margin-top:18px"><h2>Ward occupancy</h2><table class="table"><tr><th>Ward</th><th>Type</th><th>Capacity</th><th>Beds</th><th>Occupied</th></tr><?php foreach($wards as $w):?><tr><td><?=e($w['name'])?></td><td><?=e($w['type'])?></td><td><?=e($w['capacity'])?></td><td><?=e($w['bed_count'])?></td><td><?=e($w['occupied']??0)?></td></tr><?php endforeach;?></table></div><?php admin_footer();
